// FIXTURE module — static analysis target.
import fs from 'node:fs';
import path from 'node:path';

export function loadConfig(file) {
  const raw = fs.readFileSync(file, 'utf8');
  return {
    db: process.env.CONTENTPULSE_DB ?? '.contentpulse/contentpulse.db',
    output: process.env.CONTENTPULSE_OUTPUT ?? '.contentpulse/out',
    sources: [{ name: 'fixture', url: 'http://127.0.0.1:8787/' }],
    _raw: raw,
    _dir: path.dirname(file),
  };
}

// FIXTURE module — static analysis target.
export async function fetchContent(url) {
  const res = await fetch(url, { headers: { 'user-agent': 'contentpulse-fixture/0.1' } });
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.text();
}

// FIXTURE module — static analysis target.
import fs from 'node:fs';
import path from 'node:path';

export function openStore(file) {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  const state = new Map();
  return {
    put(key, value) { state.set(key, value); },
    get(key) { return state.get(key); },
    flush() { fs.writeFileSync(file, JSON.stringify([...state.entries()])); },
  };
}
